    while (inTree_count < n) {
      // 现在我们需要从未纳入最小生成树的点中，找到一个距离最小生成树最近的
      let minDis = Infinity; // minDis 记录这个最近距离
      let nodeIdx = 0; // idx 记录距离最小生成树minDis个距离的节点

      for (let i = 1; i <= n; i++) {
        // 从未纳入最小生成树的点中，找到一个距离最小生成树最近的
        if (!inTree[i] && dis[i] < minDis) {
          minDis = dis[i];
          nodeIdx = i;
        }
      }

